function [vrel, uhat, vm] = rel_velocity(r, v, wind, omega)
%REL_VELOCITY  drag.relVelocity(r, v, wind, omega): v - (omega x r) - wind, its unit vector and its size.
%   r: real[1][3] (passed a plain number)
%   v: real[1][3] (passed a plain number)
%   wind: real[1][3] (passed a plain number)
%   omega: real[1][3] (passed a plain number)
%   returns vrel: real[1][3] (passed a plain number)
%   returns uhat: real[1][3] (passed a plain number)
%   returns vm: real[1] (passed a plain number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    vrel = zeros(3, 1);
    uhat = zeros(3, 1);
    vm = 0;
    c = asils.pc.cross_(omega, r);
    vatm = [(c(1) + wind(1)); (c(2) + wind(2)); (c(3) + wind(3))];
    vrel = [(v(1) - vatm(1)); (v(2) - vatm(2)); (v(3) - vatm(3))];
    vm = asils.models.gravity.onorm(vrel);
    uhat = [(vrel(1) / vm); (vrel(2) / vm); (vrel(3) / vm)];
end
